"""Preserve five systemic time/casting proposals and expose actual unresolved decisions."""
from copy import deepcopy
from datetime import datetime,timezone
import json,re,zipfile
from apply_di7_ap_as_01 import G,R,A,info,encoded
from prepare_ac5_current_interfaces_01 import at

IDS=['absolute-zero','chrono-lock','time-skip','quicken-cast','contingency']
FORKS=[
 ('TC5-Q01',['absolute-zero'],'Printed one creature frozen in time,10d6cold,CON negates all; Core Instantaneous.','A: earlier concentration through original caster next future regularSTART, damage first then one hard-admitted finite suspension. B: instantaneous cold only or a different explicit finite endpoint.','Recommend A to retain actual time-freezing rather than deleting the promise. Full save success negates both; failed-save cold survives spent control allowance; cold immunity alone is not temporal immunity. No frozen-water inventory or generic Petrified.'),
 ('TC5-Q02',['chrono-lock'],'Divination says no-save one-round freeze; Universal says no-actions/no-damage one round.','A: earlier explicit harmonized no-save/no-damage behavior in both schools. B: preserve distinct school-specific suspension protections.','Recommend A only as named local union, retaining both full placements/access. No save may be silently added. This choice does not merge generating schools or make willingness bypass the proposed hard-control gate.'),
 ('TC5-Q03',['absolute-zero','chrono-lock'],'Two local temporal-body proposals have different clocks/concentration.','A: retain AbsoluteZero source-next-futureSTART/concentration and ChronoLock target-first-futureEND/nonconcentration, excluding underway target turn, with real outside6sec clocks. B: unify both to one clock/concentration rule.','Recommend A; similar appearance does not erase source-specific endpoints. Keep real regular markers/elapsed deadlines during suppression, no extra-turn advance, no replayed missed event. This asks for local endpoints, not a global time rewrite.'),
 ('TC5-Q04',['absolute-zero','chrono-lock'],'Full suspension protects body from new payloads and pauses immediate metabolism; world deadlines continue.','A: retain body immobility/payload prevention, skipped death saves/periodic bodily outputs and no rest credit, while exact world-timed lethal-track transitions still occur. B: defer every world-caused bodily state change, including lethal tracks, until release.','Recommend A as the ChronoLock proposal, but reconcile AbsoluteZero explicitly. Classify directHP loss, condition expiry, pending Stable recovery, genuine track6 death and support loss. No generic stasis condition or death prevention is inherited from Time Loop.'),
 ('TC5-Q05',['absolute-zero','chrono-lock'],'Body-emitted aura and held gear behavior versus independent fields/projectiles.','A: earlier ChronoLock rule suppresses body-emitted outputs/voluntary commands; independent external effects keep actual sources. Held real gear cannot be detached while held, but other carried/mounted creatures are not frozen. B: all ongoing outputs persist or every related effect freezes.','Recommend A, and decide whether the same bounded output rule belongs in AbsoluteZero. Keep exact pending commitments and unavoidable maintenance deadlines; do not restore ended concentration or create a new creature freeze from association.'),
 ('TC5-Q06',['absolute-zero','chrono-lock'],'Protected body versus reachable rank-six magical application.','A: an otherwise actually eligible dispel/suppression targets the real ongoing application despite body payload protection. B: protect the application itself from every removal.','Recommend A as earlier proposal, with actual source perception/rank/range/operation snapshots and no hidden locator. Suppression resumes only on a surviving eligible identity at its current position, original endpoint and spent guard; source dismissal clauses remain distinct.'),
 ('TC5-Q07',['time-skip'],'Source BonusAction,60ft,skip next round and return with surprise BonusAction.','A: earlier explicit self-only correction, arm on own regular turn,nextSTARTdeparture,followingSTARTreturn, outside+6then6absence. B: preserve60ft as an ally-target grant or depart immediately.','Recommend A as prior local proposal while preserving the60ft metadata conflict. Actual next-turn interval is skipped; departure ends current concentration; no new plane or rewind. The extra immediate returnBA is additional to the ordinary returnBA, not an automatic Surprise condition.'),
 ('TC5-Q08',['time-skip'],'Already attached damage/life/world effects during temporal absence.','A: actual already-attached effects continue only through their own real eligibility, while no new outside target can select absent body and no virtual optional activation occurs. B: freeze all internal bodily effects for the interval.','Recommend A to preserve original poison/dead-remains return obligation. Bind an actual supported periodic source and exact due marker before current-case authorship. Required saves/life events are distinct from unavailable voluntary choices; no invented poison or ignored source geometry.'),
 ('TC5-Q09',['time-skip'],'Earlier procedure permits full suppression/removal during absence but supplies no concrete reachable locus.','A: actual removal needs an already qualifying source route to the temporal application; no empty-anchor target/field is automatically sufficient. B: author a new explicit local anchor/marker that makes the absent spell reachable.','Recommend A unless a concrete necessary source warrants B. If B is chosen, give full visible/hidden/perception/line/range behavior rather than a free diagnosis. Do not silently treat the absent creature as occupying its departure space; early return grants no return bonus.'),
 ('TC5-Q10',['time-skip'],'One immediate additional return BonusAction and occupied return anchor.','A: prior same-anchor/squeeze/nearest-unobstructed-adjacent/pending-conflict return and one immediately used/lost BA excluding TimeSkip and action/turn generation. B: grant a full extra turn, banked BA or remote safe square.','Recommend A. Actual death returns the same remains with no BA. A returned placement conflict is not extended absence/invulnerability. Existing command/offense caps persist even with two actual BA opportunities.'),
 ('TC5-Q11',['quicken-cast'],'Action/10RP/60ft source promises two rank≤3 spells in one turn.','A: earlier Self-only enabling Action with two declared one-Action child identities, separately paid sequential actual casts. B: ally-target permission using60ft or count Quicken as one of the two.','Recommend A while explicitly preserving the range conflict. Children keep actual selected-class rank, source acquisition, costs, components, counters, concentration and current targets. No substitute undeclared spell on failure. Distinguish this local child permission from granting a general extra fullAction.'),
 ('TC5-Q12',['quicken-cast'],'Original Wizard example incorrectly used Dissonance1,1,2; interaction with genuine extra Actions and nested counters needs exact chronology.','A: use current actual class engine: fresh prepared Wizard9 Quicken0, first distinct rank3child0, repeated samechild base1+Refrain1=>2 total, assuming no intervening own cast; direct separately paid enabler casts retain genuine action/per-round restrictions. B: retain old generic cadence or silently add a universal once/turn cap.','Recommend A. This is an inherited example correction, not a new Wizard engine. Discuss genuinely sourced Haste/additional Action compatibility and copy/replay denial explicitly; no blanket cap should be invented merely for convenience.'),
 ('TC5-Q13',['contingency'],'Source automatic activation lacks storage time, payload ranks and loading mechanics.','A: earlier one24h nonconcentration frame, load within60sec, one separately paid rank0–5one-Action ordinary spell. B: finite short-lived trigger with no separately stored cast.','Recommend A as the complete explicit new design, but review exact payment/initial eligibility/counter/concentration displacement. A loading attempt consumes the opportunity; stored payload is the original cast, not a free copy. Glyph of Warding does not authorize these new storage mechanics.'),
 ('TC5-Q14',['contingency'],'Bound-body sensing, stored origin and automatic after-event release.','A: prior ordinary local30ft sensing plus explicitly limited bound-body transitions/deadline, one-shot consume before release after complete event, original caster provenance and body-current origin. B: permit interruption/prevention or read hidden state without a declared sensor.','Recommend A with full damage-root and immutable source-operation mapping supplied for each actual payload kind. No old counter window reopens. A proposed root checkpoint for stored damage must not silently generalize accepted Null mappings or add a sixth Fate presentation.'),
 ('TC5-Q15',['contingency'],'Concentration at load/release, one owner/round discharge and finite release chains.','A: earlier paid loading displaces old concentration; no concentration held in storage; release reestablishes only if original caster satisfies actual conscious/range60/LoE requirements. Nonconcentration payload retains exact living-owner/same-plane conditions; finite prearmed dispatch set. B: maintain payload concentration while stored or allow unconstrained remote/multicast release.','Recommend A only as explicit local exception. Recheck invalid/dead recipients, full frame suppression, missed transient/deadline events and actual source-owned round cap. No generic scheduler or global stored-magic permission is inferred.'),
 ('TC5-Q16',['contingency'],'Original generic healing-payload scenario lacks an actual direct-healing ordinary spell; class techniques are not legal payloads.','A: preserve it as a conditional obligation until a genuine eligible spell is supplied; compare pending rank5 GraveGift separately without granting it acceptance. B: borrow a Cleric class heal or invent a rank3 healing spell.','Recommend A. A full catalog source-text scan is supplied, not proof of all later derived healing. GraveGift is pending actual companion/life review and proposes direct recovery, not ordinary healing; loading itself must meet its Dying/Stable target and HP-payment conditions. A stored attack that heals its caster is not automatically a rescue of the bound recipient.')
]


def main():
    out=R/'data/director/spell_review/time_cast_5_conference_01.json';root=A/'time-cast5-conference-01';check=A/'TIME_CAST_5_CONFERENCE_01_CHECK.json';archive=A/'DD_Time_Cast_5_Conference_01.zip';req=A/'TIME_CAST_5_CONFERENCE_01_REQUEST.txt';prep=A/'TIME_CAST_5_CONFERENCE_01_PREPARATION.json'
    assert all(not p.exists() for p in [out,root,check,archive,req,prep])
    sources={};checks=[]
    def read(p):return json.loads(p.read_bytes())
    def bind(p):
        b=info(p);sources[b['path']]=b;return b
    def ck(label,v):
        checks.append({'check':label,'passed':bool(v)});assert v,label
    qp=R/'data/director/spell_review/remaining_work_queue_06.json';cp=R/'data/public/spell_playtests/catalog.json';ip=R/'data/public/spell_playtests/authored_review_index.json';rp=R/'data/director/spell_review/accepted_interface_registry_04.json';queue,catalog,index,reg=map(read,[qp,cp,ip,rp])
    base=[qp,cp,ip,rp,R/'data/public/class_playtests/wizard.json',R/'data/public/class_playtests/cleric.json',R/'data/public/class_playtests/mage.json',R/'data/public/expedition_candidate/complete_candidate.json',R/'tools/prepare_time_cast5_conference_01.py']
    names=['TEMPORAL_CONTROL_PLAYTEST.md','TEMPORAL_PARENT_PLAYTEST.md','TEMPORAL_KERNEL_PLAYTEST.md','TEMPORAL_KERNEL_REVIEW_STATUS.json','TEMPORAL_CONTROL_WORLD_REVIEW_STATUS.json','TEMPORAL_PARENT_REVIEW_STATUS.json','BODY_EQUIPMENT_PLAYTEST.md','COMBAT_ACTION_PLAYTEST.md','CONTROL_STATES_PLAYTEST.md','HEALING_DEATH_PLAYTEST.md','CREATURE_LIFECYCLE_PLAYTEST.md','DAMAGE_SHARING_PLAYTEST.md','MAXIMUM_HP_PLAYTEST.md','CHARACTER_CREATION_PLAYTEST.md','VIDEO_GAME_ONLY_DIRECTIVE.md']
    for p in base+[R/'docs/mechanics'/n for n in names]:bind(p)
    records=[];shared={};cases=[]
    for ident in IDS:
        row=next(r for r in queue['rows'] if r['id']==ident);ck('Not already queued '+ident,row['currentGroup'] is None)
        prior=row['previousAuthoringMapRowUnchanged']['completeEarlierProposalRecords'][0];p=G/prior['source']['path'];ck('Full original source '+ident,bind(p)==prior['source']);doc=read(p);rec=at(doc,prior['recordPointer']);card=next(s for s in catalog['spells'] if s['id']==ident);entry=next(e for e in index['entries'] if e['id']==ident)
        ck('Complete procedure '+ident,rec['spellId']==ident and len(rec['procedure'])>100);ck('Unchanged exact access/source '+ident,rec['fullSourceAndCurrentAccessRecord']==card);ck('Pending identity '+ident,entry['authoredStatus']=='pending-authored-procedure')
        records.append({'spellId':ident,'source':info(p),'pointer':prior['recordPointer'],'completeOriginalRecordUnchanged':deepcopy(rec),'completeCurrentCatalogSourceAndAccess':deepcopy(card),'indexEntry':deepcopy(entry),'riskTier':'C','status':'Earlier full proposal; design choices not adopted.'})
        shared[str(p)]={'source':info(p),'completeOriginalSharedProposalUnchanged':deepcopy(doc['sharedProposal']),'completeOriginalJointIssuesUnchanged':deepcopy(doc['explicitJointIssues'])}
        for n,t in enumerate(rec['workedCases']):cases.append({'id':t.split(':',1)[0],'spellId':ident,'originalTextUnchanged':t,'source':info(p),'pointer':prior['recordPointer']+f'/workedCases/{n}'})
        for key in ['catalog','core']:ck('Underlying '+key+' '+ident,bind(R/card['source'][key+'Path'])['sha256']==card['source'][key+'Sha256'])
    inherited=[]
    for n in list(range(15))+[22,36,39,40,49,50,51,80,81,82,86,91,92]:
        e=reg['entries'][n];b=e['currentAuthoritativeSource'];a=bind(G/b['path']);ck('Exact accepted authority '+str(n),a['bytes']==b['bytes'] and a['sha256']==b['sha256']);inherited.append({'registryPointer':f'/entries/{n}','completeEntryUnchanged':deepcopy(e),'scopeLimit':'Exact accepted source only; no temporal-stasis/deferred-cast extension by analogy.'})
    counterparts=[]
    for ident in ['fireball','haste','glyph-of-warding','shield','stoneflesh','finger-of-the-dead','lifedraw','vampiric-touch']:
        entry=next(e for e in index['entries'] if e['id']==ident);ck('Reviewed counterpart '+ident,entry['authoredStatus']=='reviewed-authored-operational-playtest');p=(ip.parent/entry['procedureFile']).resolve();doc=read(p);ptr=entry.get('wholeCardPointer',entry['procedurePointer']);counterparts.append({'spellId':ident,'source':bind(p),'pointer':ptr,'completeCurrentCard':deepcopy(at(doc,ptr)),'completeSharedRules':deepcopy(doc.get('sharedRules',{})),'indexEntry':deepcopy(entry)})
    pendingp=R/'data/director/spell_review/companion_life_10_conference_01.json';pendingdoc=read(pendingp);pending={'source':bind(pendingp),'status':'Actual source conference active, not accepted authority. Full packet candidate supplied for pending GraveGift direct-recovery comparison.'}
    # Record the bounded scan and complete matching cards; no regex result becomes an invented spell.
    matches=[{'pointer':f'/spells/{i}','completeCard':deepcopy(s)} for i,s in enumerate(catalog['spells']) if re.search(r'restore|regain|heal',s['source']['original']['description'],re.I) and any(v['rank']<=5 for v in s['classAccess'].values())]
    search={'source':info(cp),'scope':'Every current catalog original description; case-insensitive restore/regain/heal, at least one actual class rank<=5. This is not an exhaustive semantic search of all derived healing or a no-healing theorem.','completeMatchingCards':matches,'classTechniquesRemainIneligiblePayloads':True}
    questions=[{'id':qid,'spellIds':ids,'exactSourceOrConflict':promise,'options':opts,'recommendationAndConsequences':rec,'decisionSelected':False} for qid,ids,promise,opts,rec in FORKS]
    semantic=[{'spellId':r['spellId'],'riskTier':'C','sourcePreserved':True,'fullEarlierNewChoices':r['completeOriginalRecordUnchanged'].get('newChoices'),'genuineQuestionIds':[q['id'] for q in questions if r['spellId'] in q['spellIds']],'inherited':'Actual casting/rank/access/cost, whole-Action guard, original clock and source history, body/cargo conservation, genuine life state and scoped removal rules. Existing Time Loop policy/code is bounded and does not authorize these spells.'} for r in records]
    findings=[
      {'id':'TC5-F01','classification':'EXAMPLE ERROR','caseId':'UN5-02-A','finding':'For fresh prepared Wizard9 with no intervening own cast, first Quicken base0, first distinct prepared rank3child base0, repeat child base1 plusRefrain1 gives totalD2, not4. The RP arithmetic32-10-5-5=12 remains. Real acquired child spells still must be supplied.'},
      {'id':'TC5-F02','classification':'MISSING ACTUAL SOURCE','caseId':'TU6-11-B','finding':'An unnamed generic healing payload is not an actual rank<=5ordinary spell. The attached full source scan finds lifetaps and a pending GraveGift; class heals cannot substitute. Preserve the original rescue obligation conditionally until genuine spell/target/loading legality is established.'},
      {'id':'TC5-F03','classification':'MISSING REMOVAL LOCUS / DESIGN QUESTION','caseId':'TU4-08-B','finding':'TimeSkip removes local occupancy/target selection, so a field at the empty old anchor is not automatically source suppression. The earlier generic early-return clause needs a genuinely qualifying removal route or explicitly new anchor semantics.'},
      {'id':'TC5-F04','classification':'PROCEDURE RECONCILIATION','spellIds':['absolute-zero','chrono-lock'],'finding':'Explicit world-timed lethal transitions and body-emitted aura output are detailed in ChronoLock but not equally explicit in AbsoluteZero. Similar temporal prose does not prove identical behavior; conference must choose each local scope.'},
      {'id':'TC5-F05','classification':'NEW DAMAGE-ROOT MAPPING','spellIds':['contingency'],'finding':'Stored release is no second cast, but current payload resolution needs explicit damage-root/Null checkpoints and actual source provenance. Existing later-discharge examples are scoped precedents, not automatic new Contingency approval.'},
      {'id':'TC5-F06','classification':'RUNTIME SCOPE','spellIds':IDS,'finding':'Temporal kernel/parent/control approvals cover bounded components. Full TimeLoop remains unavailable; none of these local spells is implemented or approved because related helper tests exist.'},
    ]
    ck('Five unique pending sources',len(records)==len(set(IDS))==5);ck('Ten original cases',len(cases)==len({c['id'] for c in cases})==10);ck('Sixteen questions',len(questions)==16);ck('Catalog membership unchanged',index['authoredCounts']=={'reviewed':480,'pending':368})
    ck('Original Quicken RP arithmetic',32-10-5-5==12);ck('Corrected inherited Wizard cadence',0+0+(1+1)==2);ck('Original frame RP arithmetic',40-13-5==22);ck('One absence interval',5-4==1);ck('No hidden current vectors',True)
    root.mkdir();frozen=[]
    for b in sources.values():
        p=G/b['path'];ck('Source unchanged '+b['path'],info(p)==b);dst=root/'sources'/b['path'];dst.parent.mkdir(parents=True,exist_ok=True);dst.write_bytes(p.read_bytes());ck('Frozen byte equality '+b['path'],dst.read_bytes()==p.read_bytes());frozen.append({**b,'frozenCopy':dst.relative_to(G).as_posix()})
    result={'id':'TIME-CAST-5-CONFERENCE-01','recordedAtUtc':datetime.now(timezone.utc).isoformat(),'status':'PREAUTHORSHIP_CONFERENCE_PREPARED_UNSENT','developmentDirection':'video-game-only','records':records,'all10OriginalScenarios':cases,'completeOriginalSharedProposalsUnchanged':list(shared.values()),'sharedRouting':'These are full historical proposals. Only each identity’s actual casting/clock/body/source scopes apply; unrelated divination information, asset, material, portal and other per-card exceptions grant nothing. Current accepted exact sources override superseded generic Wizard cadence/status prose.','currentAcceptedInterfaceComparisons':inherited,'completeAcceptedCounterparts':counterparts,'pendingGraveGiftComparison':pending,'catalogHealingSourceSearch':search,'semanticDelta':semantic,'questions':questions,'findings':findings,'riskCounts':{'C':5},'currentVectors':[],'currentVectorScope':'Zero new complete encounters at this preauthorship stage. Original10 scenarios retain all material obligations, but unsupplied attack/poison/healing/late-removal premises are not claimed as proved runtime or legal complete encounters.','sourceBindings':list(sources.values()),'countsUnchanged':{'reviewed':480,'pending':368},'newRuleAdoptions':0,'runtimeTestsExecuted':0,'humanPlaytests':0,'cosmologyDecisions':0,'sourceInformationDeleted':0}
    out.write_bytes(encoded(result));check.write_bytes(encoded({'candidate':info(out),'checks':checks,'checkCount':len(checks),'sourceCount':len(sources),'fullProcedures':5,'originalCases':10,'newCurrentVectors':0,'questions':16,'failures':0,'validationScope':'Exact source/access/history/membership and limited conditional arithmetic; not final semantic acceptance or runtime.'}))
    (root/'MANIFEST.json').write_bytes(encoded({'candidate':info(out),'check':info(check),'files':list(sources.values()),'frozenSources':frozen,'sourceCount':len(sources),'newRuleAdoptions':0}))
    (root/'README.md').write_text('''# Time/casting5 preauthorship conference01

Read all five complete earlier procedures and original access/placement records, ten unchanged scenario obligations, full accepted counterparts, temporal scope documents, semantic delta and sixteen actual decision questions. No substantial new systemic rule is chosen in this preparation. Zero new current encounter vectors are supplied. The purpose is to decide the local rules before full source-qualified current cases and final exact artifacts are authored.

Absolute Zero and Chrono Lock are finite body suspension proposals with distinct clocks, not enabled Time Loop or generic Frozen/Petrified. Time Skip is proposed absence with actual history/return, not stasis. Quicken Cast proposes two real paid child casts in its enabling Action. Contingency proposes a separately paid stored cast and new automatic release. Read each independent source boundary; do not create one global temporal engine by analogy.

Current Wizard cadence corrects original Quicken D4 to D2 under the stated first-distinct prepared assumptions, while keeping RP32-10-5-5=12. The original Contingency healing example has no named legal spell; a full bounded catalog search and pending GraveGift comparison are supplied. Do not substitute a class heal, invent Cure Wounds, or describe pending direct recovery as ordinary healing. Time Skip has no automatically targetable old-anchor body during absence. Contingency damage needs explicit actual root mapping, with no new Fate disclosure entry.

Return downloadable per-spell/per-question dispositions and complete exact source-linked procedure replacements when necessary. Preserve every old text/case ID. After actual decisions, current encounter authorship and exact acceptance remain necessary. No new adoption, runtime implementation, human gameplay, balance, cosmology/canon,75-domain closure, whole-game flow or release approval;480/368 remains unchanged.
''',encoding='utf8',newline='\n')
    with zipfile.ZipFile(archive,'x',zipfile.ZIP_DEFLATED,compresslevel=9) as z:
        for n in ['README.md','MANIFEST.json']:z.write(root/n,n)
        z.write(out,'CANDIDATE.json');z.write(check,'PREFLIGHT.json')
        for b in frozen:z.write(G/b['frozenCopy'],'sources/'+b['path'])
    with zipfile.ZipFile(archive) as z:
        assert z.testzip() is None and z.read('CANDIDATE.json')==out.read_bytes()
        for b in frozen:assert z.read('sources/'+b['path'])==(G/b['frozenCopy']).read_bytes()
    b=info(archive);req.write_text(f'Please conduct the Time/Casting5 preauthorship conference using {archive.name} ({b["bytes"]} bytes; SHA256 {b["sha256"]}). Read all5 full original procedures,10 preserved scenarios,16 explicit questions and complete sources/counterparts. Zero new current encounter vectors are submitted. Decide bounded AbsoluteZero/ChronoLock stasis, TimeSkip absence and reachable removal, Quicken two paid real child casts, and Contingency storage/trigger/release/root mapping. Preserve current inherited Wizard cadence (exampleD2 not4), fixed clock/body/history rules and the unavailable fullTimeLoop boundary. A generic healing payload is unsupplied; class heals cannot substitute, and pending GraveGift is not adopted authority. Return downloadable full per-spell/per-question dispositions and exact source-linked proposed replacements if required. This is not final exact acceptance or any runtime/human/balance/cosmology/domain approval.480 reviewed/368 pending remain.\n',encoding='utf8',newline='\n')
    prep.write_bytes(encoded({'archive':b,'candidate':info(out),'manifest':info(root/'MANIFEST.json'),'check':info(check),'request':info(req),'sourceCount':len(sources),'allArchiveSourcesVerified':True,'status':'Prepared UNSENT; companion/life10 remains the actual active GPT conference.','newRuleAdoptions':0}));print(json.dumps({'archive':b,'candidate':info(out),'preparation':info(prep),'sources':len(sources),'checks':len(checks),'originalCases':10,'questions':16}))


if __name__=='__main__':main()
